(function () {
    "use strict";

    var MEASURES_PER_SLOT = 2;
    var FRAMES_PER_TRIGGER = 2;
    var STYLE_FRAMES = [0, 1];
    var ANCESTOR_LIMIT = 10;
    var RECT_READS_PER_FRAME = 5;
    var VIEWABLE_RATIO = 0.5;
    var VIEWABLE_FRAMES = 2;
    var VERIFY_FRAMES = 2;
    var SCAN_SCRIPT = "tp/verify/scan.js";
    var SAMPLE_ON_MUTATION = true;
    var CLOCK_BASE = Date.UTC(2026, 10, 2, 7, 15, 0);

    var root = window;
    var states = new Map();
    var slotListeners = [];
    var reports = [];
    var running = false;
    var framesLeft = 0;
    var pendingJobs = 0;
    var frameIndex = 0;
    var finishRun = null;

    function track(promise) {
        var work = root.__benchmarkWork;
        return work ? work.track(promise) : promise;
    }

    function now() {
        return CLOCK_BASE + performance.now();
    }

    function runSafely(callback) {
        return function () {
            try {
                return callback.apply(this, arguments);
            } catch (error) {
                reports.push({ type: "error", message: String(error && error.message) });
                return undefined;
            }
        };
    }

    function sink(text) {
        return text.length;
    }

    function flushReports() {
        if (!reports.length)
            return;
        sink(JSON.stringify({ t: now(), events: reports.splice(0, reports.length) }));
    }

    function trackSlot(element) {
        if (states.has(element))
            return;
        var state = {
            element: element,
            name: element.getAttribute("data-commercial-slot"),
            ratio: 0,
            rect: null,
            hidden: false,
            inViewFrames: 0,
            viewable: false,
            viewableTimer: false,
            lastSeen: 0,
            observer: null,
        };
        states.set(element, state);
        state.observer = new IntersectionObserver(runSafely(onIntersect), { threshold: [0, 0.25, 0.5, 0.75, 1] });
        state.observer.observe(element);
        for (var i = 0; i < slotListeners.length; i++)
            slotListeners[i](element);
    }

    function onIntersect(entries) {
        for (var i = 0; i < entries.length; i++) {
            var state = states.get(entries[i].target);
            if (!state)
                continue;
            state.ratio = entries[i].intersectionRatio;
            state.lastSeen = now();
            if (state.ratio >= VIEWABLE_RATIO && !state.viewable && !state.viewableTimer) {
                state.viewableTimer = true;
                markViewable(state);
            }
        }
        startRun("intersection");
    }

    function markViewable(state) {
        track(
            new Promise(function (resolve) {
                setTimeout(
                    runSafely(function () {
                        state.viewable = true;
                        reports.push({ type: "viewable", slot: state.name, t: now() });
                        resolve();
                    }),
                    0
                );
            })
        );
    }

    function measureGeometry(state) {
        var rect = state.element.getBoundingClientRect();
        for (var i = 1; i < RECT_READS_PER_FRAME; i++)
            rect = (i % 2 ? state.element.parentElement : state.element).getBoundingClientRect();
        state.rect = rect;
        var width = Math.max(0, Math.min(rect.right, root.innerWidth) - Math.max(rect.left, 0));
        var height = Math.max(0, Math.min(rect.bottom, root.innerHeight) - Math.max(rect.top, 0));
        var area = rect.width * rect.height;
        state.geometryRatio = area > 0 ? (width * height) / area : 0;
    }

    function measureStyles(state, frame) {
        if (STYLE_FRAMES.indexOf(frame) < 0)
            return;
        var hidden = false;
        var node = state.element;
        for (var depth = 0; node && depth < ANCESTOR_LIMIT; depth++) {
            var style = getComputedStyle(node);
            if (style.display === "none" || style.visibility === "hidden" || style.opacity === "0")
                hidden = true;
            node = node.parentElement;
        }
        state.hidden = hidden;
    }

    function measureOcclusion(state, frame) {
        if (STYLE_FRAMES.indexOf(frame) < 0 || !state.rect || state.rect.width === 0)
            return;
        var x = state.rect.left + state.rect.width / 2;
        var y = state.rect.top + state.rect.height / 2;
        if (x < 0 || y < 0 || x > root.innerWidth || y > root.innerHeight)
            return;
        var hit = document.elementFromPoint(x, y);
        state.occluded = !!hit && !state.element.contains(hit) && !hit.contains(state.element);
    }

    function measureViewport(state) {
        var other = 0;
        states.forEach(function (candidate, element) {
            if (element !== state.element && states.get(element).rect && state.rect)
                other += Math.abs(candidate.rect.top - state.rect.top) < 1 ? 1 : 0;
        });
        state.overlaps = other;
        state.scroll = root.scrollY;
    }

    function measureTiming(state) {
        var visible = state.geometryRatio >= VIEWABLE_RATIO && !state.hidden && !state.occluded && document.visibilityState === "visible";
        state.inViewFrames = visible ? state.inViewFrames + 1 : 0;
        if (state.inViewFrames >= VIEWABLE_FRAMES && !state.viewable && !state.viewableTimer) {
            state.viewableTimer = true;
            markViewable(state);
        }
    }

    var MEASURES = [
        function (state) {
            measureGeometry(state);
        },
        measureStyles,
        measureOcclusion,
        function (state) {
            measureViewport(state);
        },
        function (state) {
            measureTiming(state);
        },
    ];

    function runJob(state, measure, frame) {
        MEASURES[measure % MEASURES.length](state, frame);
        if (--pendingJobs === 0)
            frameDone();
    }

    function scheduleFrame() {
        var jobs = [];
        states.forEach(function (state) {
            for (var m = 0; m < MEASURES_PER_SLOT; m++)
                jobs.push([state, m]);
        });
        pendingJobs = jobs.length;
        if (!pendingJobs) {
            finishRun();
            return;
        }
        var frame = frameIndex;
        for (var i = 0; i < jobs.length; i++) {
            (function (job) {
                requestAnimationFrame(
                    runSafely(function () {
                        runJob(job[0], job[1], frame);
                    })
                );
            })(jobs[i]);
        }
    }

    function frameDone() {
        framesLeft--;
        frameIndex++;
        if (framesLeft > 0)
            scheduleFrame();
        else
            finishRun();
    }

    function startRun(reason) {
        if (!states.size)
            return;
        framesLeft = FRAMES_PER_TRIGGER;
        if (running)
            return;
        running = true;
        frameIndex = 0;
        track(
            new Promise(function (resolve) {
                finishRun = function () {
                    running = false;
                    reports.push({ type: "sampled", reason: reason, slots: states.size });
                    flushReports();
                    resolve();
                };
            })
        );
        scheduleFrame();
    }

    function discoverSlots(node) {
        if (node.nodeType !== 1)
            return;
        if (node.hasAttribute("data-commercial-slot"))
            trackSlot(node);
        if (node.childElementCount) {
            var inner = node.querySelectorAll("[data-commercial-slot]");
            for (var i = 0; i < inner.length; i++)
                trackSlot(inner[i]);
        }
    }

    var onMutations = runSafely(function (records) {
        for (var i = 0; i < records.length; i++) {
            var added = records[i].addedNodes;
            for (var j = 0; j < added.length; j++)
                discoverSlots(added[j]);
        }
        if (SAMPLE_ON_MUTATION)
            startRun("mutation");
    });

    function createFrames() {
        for (var i = 0; i < VERIFY_FRAMES; i++) {
            var frame = document.createElement("iframe");
            frame.setAttribute("aria-hidden", "true");
            frame.setAttribute("tabindex", "-1");
            frame.title = "";
            frame.width = "0";
            frame.height = "0";
            frame.style.cssText = "position:absolute;width:0;height:0;border:0;visibility:hidden";
            frame.srcdoc = '<!doctype html><script>parent.postMessage({ type: "measure-ready", index: ' + i + " }, '*');<\/script>";
            track(
                new Promise(function (resolve) {
                    frame.addEventListener("load", function () {
                        resolve();
                    });
                })
            );
            document.body.appendChild(frame);
        }
    }

    function loadScan() {
        track(
            new Promise(function (resolve) {
                var script = document.createElement("script");
                script.async = true;
                script.src = SCAN_SCRIPT;
                script.onload = script.onerror = function () {
                    resolve();
                };
                document.head.appendChild(script);
            })
        );
    }

    function init() {
        root.__vm = {
            onSlot: function (callback) {
                slotListeners.push(callback);
                states.forEach(function (state, element) {
                    callback(element);
                });
            },
            isViewable: function (element) {
                var state = states.get(element);
                return !!state && state.viewable;
            },
        };
        var existing = document.querySelectorAll("[data-commercial-slot]");
        for (var i = 0; i < existing.length; i++)
            trackSlot(existing[i]);
        new MutationObserver(onMutations).observe(document.body, { childList: true, subtree: true });
        root.addEventListener("scroll", runSafely(function () { startRun("scroll"); }), { passive: true });
        root.addEventListener("resize", runSafely(function () { startRun("resize"); }), { passive: true });
        document.addEventListener("visibilitychange", runSafely(function () { startRun("visibility"); }));
        document.addEventListener("click", runSafely(function () { startRun("click"); }), { capture: true, passive: true });
        createFrames();
        loadScan();
        startRun("init");
        if (root.__benchmarkWork)
            root.__benchmarkWork.settled("verify");
    }

    runSafely(init)();
})();
